<?php declare(strict_types=1);namespace App\Modules\Subcontracts\Repositories;use App\Core\Database\Database;use App\Modules\Subcontracts\DTOs\SubcontractData;final class SubcontractRepository{public function __construct(private readonly Database$db){}public function find(int$id):?array{$r=$this->db->execute('SELECT s.*,p.project_code,p.name project_name,v.vendor_code,v.name vendor_name FROM subcontracts s JOIN projects p ON p.id=s.project_id JOIN vendors v ON v.id=s.vendor_id WHERE s.id=? LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}public function project(int$id):bool{$r=$this->db->execute('SELECT 1 FROM projects WHERE id=? LIMIT 1',[$id]);return$r instanceof \mysqli_result&&$r->num_rows>0;}public function vendor(int$id,bool$active):bool{$r=$this->db->execute("SELECT 1 FROM vendors WHERE id=? AND vendor_type IN('subcontractor','both')".($active?' AND is_active=1':'').' LIMIT 1',[$id]);return$r instanceof \mysqli_result&&$r->num_rows>0;}public function numberExists(SubcontractData$d,?int$id):bool{$sql='SELECT 1 FROM subcontracts WHERE project_id=? AND vendor_id=? AND subcontract_number=?'.($id?' AND id<>?':'').' LIMIT 1';$p=[$d->projectId,$d->vendorId,$d->number];if($id)$p[]=$id;$r=$this->db->execute($sql,$p);return$r instanceof \mysqli_result&&$r->num_rows>0;}public function create(string$code,SubcontractData$d):int{$this->db->execute("INSERT INTO subcontracts(subcontract_code,subcontract_number,project_id,vendor_id,pricing_method,title,description,contract_date,start_date,expected_end_date,contract_value,status,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?,'draft',?)",[$code,$d->number,$d->projectId,$d->vendorId,$d->pricingMethod,$d->title,$d->description,$d->contractDate,$d->startDate,$d->endDate,$d->value,$d->notes]);return(int)$this->db->connection()->insert_id;}public function update(int$id,SubcontractData$d,bool$commercial):void{if($commercial)$this->db->execute('UPDATE subcontracts SET subcontract_number=?,project_id=?,vendor_id=?,pricing_method=?,title=?,description=?,contract_date=?,start_date=?,expected_end_date=?,contract_value=?,notes=? WHERE id=?',[$d->number,$d->projectId,$d->vendorId,$d->pricingMethod,$d->title,$d->description,$d->contractDate,$d->startDate,$d->endDate,$d->value,$d->notes,$id]);else$this->db->execute('UPDATE subcontracts SET start_date=?,expected_end_date=?,notes=? WHERE id=?',[$d->startDate,$d->endDate,$d->notes,$id]);}public function status(int$id,string$s):void{$this->db->execute('UPDATE subcontracts SET status=? WHERE id=?',[$s,$id]);}public function boq(int$id):?array{$r=$this->db->execute('SELECT status FROM subcontract_boqs WHERE subcontract_id=? LIMIT 1',[$id]);$x=$r instanceof \mysqli_result?$r->fetch_assoc():null;return is_array($x)?$x:null;}public function refs():array{foreach(['projects'=>'SELECT id,project_code,name FROM projects ORDER BY project_code','vendors'=>"SELECT id,vendor_code,name,is_active FROM vendors WHERE vendor_type IN('subcontractor','both') ORDER BY name"]as$k=>$sql){$r=$this->db->execute($sql);$a[$k]=$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[];}return$a;}public function all():array{$r=$this->db->execute('SELECT s.id,s.subcontract_code,s.subcontract_number,p.name project_name,v.name vendor_name,s.title,s.pricing_method,s.contract_value,s.contract_date,s.status FROM subcontracts s JOIN projects p ON p.id=s.project_id JOIN vendors v ON v.id=s.vendor_id ORDER BY s.id DESC');return$r instanceof \mysqli_result?$r->fetch_all(MYSQLI_ASSOC):[];}}
